package com.example.assets_management.security.service;

import com.example.assets_management.branch.entity.Branch; import com.example.assets_management.company.entity.Company; import com.example.assets_management.employee.entity.Employee; import com.example.assets_management.employee.enums.UserStatus; import com.example.assets_management.employee.repository.EmployeeRepository; import com.example.assets_management.role.entity.Role; import com.example.assets_management.role.enums.RoleStatus; import com.example.assets_management.role.enums.RoleType; import com.example.assets_management.security.rbac.service.EffectivePermissionService; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.security.core.userdetails.UsernameNotFoundException; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class CustomUserDetailsServiceTest { @Mock EmployeeRepository employeeRepository; @Mock EffectivePermissionService effectivePermissionService; @InjectMocks CustomUserDetailsService service;
 @Test void shouldLoadActiveUserWithEffectivePermissions(){UUID userId=UUID.randomUUID(),companyId=UUID.randomUUID(),branchId=UUID.randomUUID(),roleId=UUID.randomUUID(); Company c=new Company();c.setId(companyId);Branch b=new Branch();b.setId(branchId);Role role=new Role();role.setId(roleId);role.setName("Asset Manager");role.setType(RoleType.SYSTEM);role.setStatus(RoleStatus.ACTIVE);Employee u=new Employee();u.setId(userId);u.setCompany(c);u.setBranch(b);u.setEmployeeCode("EMP-001");u.setFullName("Jane Smith");u.setEmail("jane@example.com");u.setPasswordHash("hash");u.setRole(role);u.setStatus(UserStatus.ACTIVE);when(employeeRepository.findByEmail(u.getEmail())).thenReturn(Optional.of(u));when(effectivePermissionService.getEffectivePermissions(userId)).thenReturn(Set.of("Asset.Asset_Master.Create"));CustomUserDetails d=(CustomUserDetails)service.loadUserByUsername(u.getEmail());assertEquals(userId,d.getUserId());assertEquals(companyId,d.getCompanyId());assertEquals(branchId,d.getBranchId());assertEquals(roleId,d.getRoleId());assertTrue(d.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("Asset.Asset_Master.Create")));assertTrue(d.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_ASSET_MANAGER")));}
 @Test void shouldDisableInactiveUser(){UUID id=UUID.randomUUID();Employee u=new Employee();u.setId(id);u.setEmail("inactive@example.com");u.setPasswordHash("encoded");u.setStatus(UserStatus.INACTIVE);when(employeeRepository.findByEmail(u.getEmail())).thenReturn(Optional.of(u));when(effectivePermissionService.getEffectivePermissions(id)).thenReturn(Set.of());assertFalse(((CustomUserDetails)service.loadUserByUsername(u.getEmail())).isEnabled());}
 @Test void shouldRejectUnknownEmail(){when(employeeRepository.findByEmail("missing@example.com")).thenReturn(Optional.empty());assertThrows(UsernameNotFoundException.class,()->service.loadUserByUsername("missing@example.com"));verifyNoInteractions(effectivePermissionService);}
}
